import { appendFileSync } from "node:fs";
export default function (pi) {
  pi.registerCommand("hello", { description: "Say hello from a", async handler(args, ctx) {
    appendFileSync("cmd.jsonl", JSON.stringify({ command: "hello", from: "a", args }) + "\n");
  } });
}

